function collectOptions(toolId) { if (toolId === "long-snap") return {}; if (toolId === "nil-toggle") return { targetValue: document.querySelector("#nil-target").value === "true", teams: selected("#nil-teams"), playerRows: selected("#nil-players"), positions: selected("#nil-positions"), classes: selected("#nil-classes"), redshirtStatuses: selected("#nil-redshirts") }; return { positions: selected("#boost-positions"), attributes: selected("#boost-attributes"), teams: selected("#team-search"), playerScope: document.querySelector("#player-scope").value, minimum: Number(document.querySelector("#minimum").value), maximum: Number(document.querySelector("#maximum").value), ratingMode: document.querySelector("#rating-mode").value }; }
function validateOptions(toolId, options) { if (toolId === "team-boost") { if (options.ratingMode === "specific" && !options.attributes.length) return "Select at least one attribute."; if (!options.teams.length) return "Select at least one team."; if (!Number.isInteger(options.minimum) || options.minimum < -99 || options.minimum > 99) return "Minimum must be a whole number from -99 through 99."; if (!Number.isInteger(options.maximum) || options.maximum < -99 || options.maximum > 99) return "Maximum must be a whole number from -99 through 99."; if (options.maximum < options.minimum) return "Maximum must be greater than or equal to minimum."; } return null; }
async function runTool(toolId, mode) { const output = document.querySelector("#run-output"), previous = state.genericPreviews.get(toolId); const options = mode === "apply" ? { planId: previous?.planId } : collectOptions(toolId); if (mode === "apply" && !options.planId) return; const invalid = mode === "preview" ? validateOptions(toolId, options) : null; if (invalid) { toast(invalid); return; } if (mode === "preview") showStandardPreviewStage(true); document.querySelectorAll("#preview,#apply").forEach(button => button.disabled = true); output.innerHTML = `<div class="status"><span class="spinner"></span><strong>${mode === "preview" ? "Building preview…" : "Creating backup and applying changes…"}</strong></div>`; try { const result = await window.cfbToolkit.runTool({ toolId, savePath: state.activeSave.path, mode, options }); if (mode === "preview") state.genericPreviews.set(toolId, result); else { state.genericPreviews.delete(toolId); state.seasonLines = null; state.seasonLinesSave = null; state.seasonLinesError = null; } renderResult(output, result); await refreshHistory(); } catch (error) { const readable = readableError(error); if (/cached result|preview has already been applied|cached result expired/i.test(readable.message)) state.genericPreviews.delete(toolId); showError(readable, output); } finally { document.querySelector("#preview").disabled = false; document.querySelector("#apply").disabled = !state.genericPreviews.has(toolId); } }
function summaryMetrics(result) { return `<div class="metric-grid">${result.summary.map(item => `<div class="metric"><strong>${escapeHtml(item.value)}</strong><small>${escapeHtml(item.label)}</small></div>`).join("")}</div>`; }
function previewChanges(result) { return [...(result.details?.changes ?? [])].map((value, index) => ({ value, index })).sort((a, b) => { const x = a.value, y = b.value; if (result.resultKind === "automatic-force-win") return Number(x.week) - Number(y.week) || String(x.awayTeam).localeCompare(String(y.awayTeam)) || String(x.homeTeam).localeCompare(String(y.homeTeam)) || a.index - b.index; return String(x.team ?? "").localeCompare(String(y.team ?? "")) || String(x.player ?? "").localeCompare(String(y.player ?? "")) || String(x.position ?? "").localeCompare(String(y.position ?? "")) || String(x.type ?? "").localeCompare(String(y.type ?? "")) || a.index - b.index; }).map(item => item.value); }
function previewFilterToolbar(result, inputId, placeholder) { const fields = [["team", "All teams"], ["position", "All positions"], ["classYear", "All class years"]], facets = result.details?.previewFacets ?? {}, selected = result.details?.searchFilters ?? {}; return `<div class="review-toolbar preview-filter-toolbar"><input class="input" id="${inputId}" placeholder="${escapeHtml(placeholder)}" value="${escapeHtml(result.details?.searchQuery ?? "")}">${fields.filter(([field]) => facets[field]?.length).map(([field, label]) => `<select class="input" data-preview-facet="${field}" aria-label="${label}"><option value="">${label}</option>${[...facets[field]].sort(field === "position" ? positionCompare : (a, b) => String(a).localeCompare(String(b), undefined, { numeric: true })).map(value => `<option value="${escapeHtml(value)}" ${selected[field] === value ? "selected" : ""}>${escapeHtml(field === "position" ? localizedPosition(value) : value)}</option>`).join("")}</select>`).join("")}</div>`; }
function equipmentSkippedNotice(result) { if (result.resultKind !== "freshman-equipment") return ""; const details = result.details ?? {}, format = reasons => Object.entries(reasons ?? {}).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([reason, count]) => `${count.toLocaleString()} — ${escapeHtml(reason)}`).join("<br>"); const regular = details.reportedSkipped ?? details.skipped ?? 0, mod = details.modFcsSkipped ?? 0; return (regular ? `<div class="notice section"><strong>Why eligible players were skipped</strong><br>${format(details.reportedSkippedReasons ?? details.skippedReasons)}</div>` : "") + (mod ? `<details class="section"><summary>Mod-added FCS players left unchanged: ${mod.toLocaleString()}</summary><p>These additional FCS rosters are counted separately from the skipped-player total above. Their equipment remains protected. This does not indicate whether a mod is currently enabled.</p><p>${format(details.modFcsSkippedReasons)}</p></details>` : ""); }
function equipmentSafeguardNotice(result) {
  if (result.resultKind === "freshman-equipment") { const pools = result.details?.facePaintPools ?? {}; const notes = Object.entries(pools).filter(([, pool]) => pool.enabled).map(([id, pool]) => { const name = id === "raw" ? "Raw Accessories" : "Unlocked"; return pool.available ? `${name}: ${pool.available} mod facepaint style${pool.available === 1 ? "" : "s"} included alongside vanilla styles.` : `${name}: no custom styles are available in this saved preview. Run a new preview to use the current facepaint catalog.`; }); return helmetBalancePreview(result.details?.helmetBalance) + (notes.length ? `<div class="status warning"><strong>Facepaint pools</strong><ul>${notes.map(note => `<li>${escapeHtml(note)}</li>`).join("")}</ul></div>` : ""); }
  if (result.resultKind !== "equipment-patcher") return "";
  const safeguards = result.details?.populationSafeguards, tattoos = result.details?.unlockedTattooPopulation, notes = [];
  for (const [cohortName, cohort] of [["FBS", safeguards?.fbs], ["Directional FCS", safeguards?.fcs]]) {
    for (const [group, stats] of Object.entries(cohort?.visors ?? {})) if (stats.limited) notes.push(`${cohortName} visor assignments capped: ${group} prevalence reached ${(stats.ceiling * 100).toFixed(0)}%.`);
    for (const [group, stats] of Object.entries(cohort?.mouthpieces ?? {})) if (stats.limited) notes.push(`${cohortName} mouthpiece assignments capped: ${group} prevalence reached ${(stats.ceiling * 100).toFixed(0)}%. The cap limits new mouthpiece additions; existing mouthpieces are not removed.`);
    if (cohort?.undershirts?.limited) notes.push(`${cohortName} undershirt assignments capped: muscular/standard no-undershirt population reached the 5% floor.`);
  }
  if (tattoos) for (const [cohortName, cohort] of [["FBS", tattoos.fbs], ["Directional FCS", tattoos.fcs]]) {
    if (!cohort?.eligiblePlayers) continue;
    const percentage = (cohort.projectedPrevalence * 100).toFixed(1);
    notes.push(cohort.existingAboveCap
      ? `${cohortName} already has ${cohort.existingTattooPlayers} tattooed eligible players, above the ${cohort.capPercentage}% cap. Existing tattoos were preserved and no new tattoos were added.`
      : `${cohortName} tattoos: ${cohort.addedTattooPlayers} added; ${cohort.projectedTattooPlayers} of ${cohort.eligiblePlayers} eligible players projected (${percentage}%, ${cohort.capPercentage}% cap). Existing tattoos were preserved.`);
  }
  return helmetBalancePreview(result.details?.helmetBalance) + (notes.length ? `<div class="notice section"><strong>Population safeguards</strong><br>${notes.map(escapeHtml).join("<br>")}</div>` : "");
}
