  const week = Number(document.querySelector("#lines-week")?.value), query = (document.querySelector("#lines-search")?.value ?? "").trim().toLowerCase();
  const games = data.rows.filter(row => row.week === week && (!query || `${row.awayTeam} ${row.homeTeam}`.toLowerCase().includes(query)));
  target.innerHTML = games.length ? games.map(row => `<article class="season-line-game"><div class="season-line-matchup"><div><img data-team-logo src="${forceLogoUrl(row.awayTeam)}" alt=""><strong>${escapeHtml(row.awayTeam)}</strong></div><span>${row.neutral ? "vs" : "at"}</span><div><img data-team-logo src="${forceLogoUrl(row.homeTeam)}" alt=""><strong>${escapeHtml(row.homeTeam)}</strong></div></div><div class="season-line-numbers"><div><small>SPREAD</small><strong>${escapeHtml(row.favorite)} ${Number(row.favoriteSpread).toFixed(1)}</strong></div><div><small>OVER / UNDER</small><strong>${Number(row.total).toFixed(1)}</strong></div><div><small>MONEYLINE</small><strong>${escapeHtml(row.favorite)} ${forceMoneyline(row.favoriteMoneyline)}</strong><span>${escapeHtml(row.underdog)} ${forceMoneyline(row.underdogMoneyline)}</span></div></div></article>`).join("") : `<div class="empty">No projected games match this week and search.</div>`;
