  if (!savePath) return;
  state.seasonLines = null; state.seasonLinesError = null; renderSeasonLines();
  try {
    const data = await window.cfbToolkit.homeLines({ modelProfile });
    if (state.activeSave?.path !== savePath) return;
    state.seasonLines = data; state.seasonLinesSave = savePath; renderSeasonLines();
  } catch (error) { if (state.activeSave?.path === savePath) { state.seasonLinesError = readableError(error).message; renderSeasonLines(); } }
