async function historyPage() { content.innerHTML = `<div class="tool-header"><div><div class="eyebrow">Activity</div><h1>Execution History</h1><p class="muted">Open a recent Preview or Apply run to revisit its review. Runs from older app versions still open their report and summary.</p></div></div><section class="card">${state.history.length ? activityRows(state.history) : `<div class="empty">No completed runs yet.</div>`}</section><section id="history-detail"></section>`; bindHistory(); }
function showHistory(id) { const entry = state.history.find(item => item.id === id); if (!entry) return; document.querySelector("#history-detail").innerHTML = `<section class="card section"><div class="tool-header"><div><h2>${escapeHtml(entry.toolName)}</h2><p class="muted">${formatDate(entry.timestamp)} · Tool v${escapeHtml(entry.toolVersion)}</p></div><span class="version">${escapeHtml(entry.mode)} · ${escapeHtml(entry.status)}</span></div><p class="muted">This older run has no saved review panel. Its summary and report remain available.</p><p><strong>Input</strong><br><span class="muted">${escapeHtml(entry.inputPath)}</span></p>${summaryMetrics(entry)}${entry.backupPath ? `<p><strong>Backup</strong><br><span class="muted">${escapeHtml(entry.backupPath)}</span></p>` : ""}${entry.reportPath ? `<p><strong>Report</strong><br><span class="muted">${escapeHtml(entry.reportPath)}</span></p><button class="button secondary" data-open="${escapeHtml(entry.reportPath)}">Open Report</button>` : ""}</section>`; document.querySelector("#history-detail [data-open]")?.addEventListener("click", event => window.cfbToolkit.openPath(event.currentTarget.dataset.open)); }
async function reportsPage() { content.innerHTML = `<div class="tool-header"><div><div class="eyebrow">Library</div><h1>Reports</h1></div></div><section class="card"><div class="status"><span class="spinner"></span>Loading reports…</div></section>`; const reports = await window.cfbToolkit.listReports(); content.innerHTML = `<div class="tool-header"><div><div class="eyebrow">Library</div><h1>Reports</h1><p class="muted">Recent reports generated by Ace&#39;s CFB Toolkit.</p></div></div><section class="card">${reports.length ? `<table><thead><tr><th>Date</th><th>Tool</th><th>Report</th><th></th></tr></thead><tbody>${reports.map(report => `<tr><td>${formatDate(report.createdAt)}</td><td>${escapeHtml(report.tool)}</td><td>${escapeHtml(report.name)}</td><td><button class="button secondary" data-open="${escapeHtml(report.path)}">Open</button></td></tr>`).join("")}</tbody></table>` : `<div class="empty">No reports yet.</div>`}</section>`; content.querySelectorAll("[data-open]").forEach(button => button.addEventListener("click", () => window.cfbToolkit.openPath(button.dataset.open))); }
async function logsPage() { const logs = await window.cfbToolkit.listLogs(); content.innerHTML = `<div class="tool-header"><div><div class="eyebrow">Troubleshooting</div><h1>Logs</h1><p class="muted">Recent app events that may help explain a problem.</p></div><button class="button danger" id="clear-logs">Clear Logs</button></div><section class="card">${logs.length ? `<table><thead><tr><th>Time</th><th>Level</th><th>Event</th><th>Tool</th><th>Details</th></tr></thead><tbody>${logs.map(log => `<tr><td>${formatDate(log.timestamp)}</td><td>${escapeHtml(log.level)}</td><td>${escapeHtml(log.event)}</td><td>${escapeHtml(log.toolId || "—")}</td><td>${escapeHtml(log.message || log.status || "—")}</td></tr>`).join("")}</tbody></table>` : `<div class="empty">No log entries yet.</div>`}</section>`; document.querySelector("#clear-logs").addEventListener("click", async () => { if (!window.confirm("Clear all logs? This cannot be undone.")) return; await window.cfbToolkit.clearLogs(); logsPage(); }); }

function bindHistory() { document.querySelectorAll("[data-history-id]").forEach(button => button.addEventListener("click", () => openHistoryRun(button.dataset.historyId))); }
function bindCommon() { document.querySelector("#select-save")?.addEventListener("click", chooseActiveSave); document.querySelector("#open-season-lines")?.addEventListener("click", () => { state.page = "season-lines"; render(); loadSeasonLines(); }); document.querySelector("#home-team-select")?.addEventListener("change", event => { state.selectedHomeTeam = event.target.value; render(); }); document.querySelector("#theme-select")?.addEventListener("change", async event => { const theme = event.target.value; document.documentElement.dataset.theme = theme; state.bootstrap.settings = await window.cfbToolkit.updateTheme(theme); applyAccentColor(state.bootstrap.settings); toast(`${theme === "light" ? "Light" : "Dark"} mode enabled`); }); bindMultiSelectEnhancements(); bindTeamPickers(); bindTeamLogoFallbacks(); bindStandardPreviewStage(); bindHistory(); bindSettingsArtwork(); if (state.page === "home") ensureHomeLines(); bindAccentSettings(); content.querySelectorAll("[data-open-tool]").forEach(button => button.addEventListener("click", () => navigate(button.dataset.openTool))); content.querySelectorAll("[data-home-page]").forEach(button => button.addEventListener("click", () => { if (button.dataset.artworkTeam) state.selectedArtworkTeam = button.dataset.artworkTeam; navigate(button.dataset.homePage); })); }
function bindRun(toolId) { document.querySelector("#preview")?.addEventListener("click", () => runTool(toolId, "preview")); document.querySelector("#apply")?.addEventListener("click", () => runTool(toolId, "apply")); if (toolId === "team-boost" || toolId === "nil-toggle") document.querySelectorAll(".standard-config-workspace input[id],.standard-config-workspace select[id]").forEach(input => input.addEventListener("change", () => { state.genericPreviews.delete(toolId); document.querySelector("#apply").disabled = true; })); }
function helpPage() {
  const section = (title, intro, items) => `<section class="card help-tool"><h2>${title}</h2><p>${intro}</p><dl>${items.map(([term, description]) => `<dt>${term}</dt><dd>${description}</dd>`).join("")}</dl></section>`;
  return `<div class="tool-header"><div><div class="eyebrow">Reference</div><h1>Help / Instructions</h1><p class="muted">Select an Active Dynasty, configure a tool, run Preview, review the proposed changes, then use Back Up &amp; Apply. Preview does not change your save.</p></div></div>
  ${section("Best Practices / When to Run", "There is generally no required tool order.", [["Using both equipment tools","Run Equipment Randomizer first, then Equipment Patcher so Patcher cleans up the randomized equipment."],["Once per preseason","Jersey Renumber, Commentary IDs, Equipment Randomizer, and Equipment Patcher are recommended once each year during preseason, though supported tools may be run later."],["Equipment season window","Equipment tools work from the week immediately before Week 0 through National Championship week. Offseason saves outside that window are rejected."],["After training results","Team Boost and Long Snap Fixer are recommended after training results, but can technically be run anytime."],["Whenever needed","Dealbreaker Fixer may be run whenever you need to clean up player dealbreakers."],["Smart Force Win","Week 0 is recommended so the whole regular season can be handled at once. It may be rerun later within Weeks 0–15."]])}
  ${section("Config Presets", "Save your preferred settings for any configurable tool using Config presets near its settings buttons.", [["Save","Enter a preset name and choose Save preset. Presets are kept on this computer after the app closes. Saving an existing name asks before replacing it."],["Load","Choose a saved preset and Load. This replaces that tool's settings and clears its old preview; it does not run or apply anything. Review the settings and create a new Preview when ready."],["Teams","Team selections and tape mixes are matched by team name, not save row. Loading is blocked if a selected team is missing. Tape mixes for teams not in the current save are ignored; new teams keep their defaults."],["Defaults","Reset to Defaults changes your current settings but does not delete saved presets. Restarting the app still starts tools at their defaults."]])}
  ${section("Jersey Renumber", "Choose one of two jersey-numbering styles.", [["Standard","Uses realistic position ranges and allows offensive and defensive players to share a number where supported."],["No Duplicates","Gives every player on a processed team a unique jersey number."],["Teams to Skip","Selected teams are left untouched. Your controlled teams start selected, but you can add or remove any team."],["NIL Players","In Standard mode, this option allows NIL players to be renumbered."],["Team traditions","Uses supported team-specific jersey numbering customs."],["Retired numbers","Keeps supported retired jersey numbers unavailable."],["Promotions","Allows eligible players to move into preferred low numbers."]])}
  ${section("Commentary ID Patcher", "Uses the toolkit's spoken-name list to suggest commentary IDs for players.", [["Sound-alike matching","Suggests similar-sounding last names for you to Accept or Reject."],["First-name fallback","Uses an exact first-name match when no last-name match is available."],["Preserve unmatched","Keeps the current ID when no match is found."],["True Freshmen only","Checks only true freshmen when enabled."],["Detailed report","Adds every scanned player to the CSV. Leave this off for normal use."],["Review decisions","Clear matches are listed automatically. Every sound-alike suggestion must be Accepted or Rejected before Apply."]])}
  ${section("Equipment Randomizer", "Copies realistic equipment combinations from high-rated players to the players you choose.", [["Donor Save","Leave this blank to copy equipment from the Active Dynasty, or choose another compatible CFB 27 save."],["# of Donors Per Position","Uses this many of the highest-overall eligible players at each position as equipment examples. When the Active Dynasty supplies the donors, those players keep their own equipment."],["Choose specific donors","Select eligible active-roster sophomores, juniors, and seniors from the Active Dynasty. Only selected players supply equipment and keep their own gear. This replaces the top-rated cutoff; no donor-save file is used."],["Mixing chances","Defaults are 10% compatible cross-position mixing and 30% multiple-donor mixing. The remainder uses one donor. The two chances must total no more than 100%. At 0% cross-position chance, donors stay at the exact position. At 100%, a compatible cross-position pool is always used when available."],["Unlocked Equipment Pool",`Disabled by default. Adds extra accessories, rubber bands, double/elbow sleeves, compression-leg layers, branded turtlenecks and mouthpieces, normal balaclavas, thigh pads, a string towel, and select gear from Orckestra’s mod. Under-lip and unidentified mask styles are not added. Each equipment category has a configurable chance, starting at 10%. Also adds 13 custom facepaint styles through the separate facepaint roll. <strong class="requirement">Requires CFB 27 Unlocked.</strong>`],["No Drip Profile","Removes selected accessories at configurable chances: WR/CB/FS/SS start at 1%; HB/TE/QB/linebackers at 3%; OL/DL/FB/K/P at 6%."],["Raw Accessories Equipment Pool",`Disabled by default. Adds Raw Slim turtlenecks in all four colors, gold/silver cross necklaces, Battle/Nike skullcaps, and 17 custom facepaint/eye-tape styles. Uses the extra gear chance separately for neckwear and skullcaps, while facepaint has its separate roll. No equipped donors are needed. <strong class="requirement">Requires DelonteRAW Raw Accessories.</strong> Both mod facepaint pools can be combined.`],["Facepaint","Facepaint is rolled separately, with a 60% chance of none. Enabling Unlocked adds 13 custom styles; Raw Accessories adds 17. Both pools can be combined. Donors do not need to wear these styles. Receiving slogans are limited to WRs and TEs; hitter slogans are limited to defensive positions."],["Shoes and gloves","These items are checked against your player\'s team brand, no matter how donors are selected. Other accessories can still come from different-brand donors. Uncatalogued original custom shoes are preserved, not copied to other players."],["Pants length","Copies the donor\'s saved pants choice, including below-knee pants. If the donor has no pants entry, the player keeps their original choice. Running the Patcher\'s Above Knee Pants pass afterward will intentionally replace long pants; leave it off for Bears Pads\' below-knee appearance."],["Equipment cleanup","Automatically removes wrist or elbow gear that would overlap certain sleeves and undershirts. Ski masks and balaclavas use hanging mouthpieces only."],["Player Pool","Skip NIL players starts on but can be turned off. Your team selection chooses who can be changed; empty means all teams. To skip teams, select All and uncheck those teams."],["Class, redshirt, position, and overall filters","Use these to choose which players may be changed. An empty multi-select means all options are allowed."],["Active rosters only","Only players currently on a team roster can receive equipment or serve as donors. Old player entries stored in the save are ignored."],["Skipped players","Players are left untouched when the toolkit cannot safely find a unique, usable equipment record for them."]])}
  ${section("Equipment Patcher", "Fixes the equipment issues you select for the players in your chosen Player Pool.", [["Above-knee pants","Changes long pants to the above-knee style."],["Helmets and facemasks","Fixes unrealistic helmet and facemask combinations for every position except offensive line. Standard Vicis Zero 2 and Balance Existing Helmets start off. With Vicis enabled, targets are 68% SpeedFlex, 15% F7 / F7 Pro, 14% Axiom, and 3% Vicis. Vicis can only be added to quarterbacks, tight ends, linebackers, and defensive linemen. Other positions use the remaining helmet families. Balancing makes only the needed swaps toward the selected target mix, spread across teams, with FBS and directional FCS counted separately. Preview shows before/after counts and targets."],["Rolled-jersey undershirts","Adds a visible undershirt to cropped jerseys that need one, while keeping the occasional no-shirt look."],["Mid socks","Usually changes mid socks to low socks and sometimes high socks. Offensive linemen keep mid socks, and players wearing spats on both feet can also keep them."],["Equipment compatibility","Fixes overlapping equipment. The shoulder-to-elbow Undershirt sleeve blocks elbow gear but allows wrist gear. Rolled Sleeve also allows wrist gear, except Wrist Coach. Full-length sleeves keep their usual restrictions."],["Nike thigh pads","Changes generic thigh pads to the Nike version."],["Visors","Adds Oakley Clear visors while keeping visor use within the position limits shown in the tool."],["Brand existing visors","Replaces generic clear, reflective, dark, and smoke visors with matching Oakley variants. Visor-free players stay visor-free; tint stays the same."],["Add mouthpieces",`Disabled by default. Adds position-appropriate mouthpieces to most eligible players without removing valid existing ones. Known non-mouthpiece items incorrectly stored in the mouthpiece slot are repaired and clearly labeled in Preview. QBs, kickers, and punters are excluded. Battle, NXTRND, Nike, and Shock hanging styles are favored. By default, new mouthpieces use team colors, black, or white. Reroll Existing Mouthpieces starts off; enable it to reroll the type, brand and color using the same pool as new mouthpieces. Branded Mouthpiece Frequency applies to both additions and rerolls. Verified branded designs are hanging pacifiers; the unbranded share keeps the position-appropriate style mix. The colorful option also adds unbranded, Battle, and NXTRND bright colors, with pink kept rare. <strong class="requirement">Requires CFB 27 Unlocked.</strong>`],["Recolor accessories",`Disabled by default. The recommended color mix is 65% white, 20% black, 10% team primary, and 5% team secondary; you can edit the percentages or choose a fixed color. Each player gets one matching accessory theme. Existing spats, wrist tape, and long/short arm tape use a separate White, Black, Primary, and Secondary percentage mix for each team. Each player rolls one tape color for their spats, wrist tape, and long/short arm tape. Match Tape to Player Accessory Color instead uses the player’s chosen accessory theme and bypasses team percentage rolls. Team-specific defaults are provided; other teams start at 95% white and 5% black. Edit any team's mix in Tape Color by team; it must total 100%. Balance to 100% adjusts your entered proportions for you. Wristbands and arm bands follow the accessory theme, and mouthpieces keep their separate color setting. Branded turtlenecks keep the logo combinations that exist in the game; if the requested cloth color is unavailable, the current item stays unchanged. <strong class="requirement">Requires CFB 27 Unlocked.</strong>`],["Add tattoos",`Disabled by default. Adds mostly arm tattoos, sometimes leg tattoos, and occasionally both to eligible active-roster QBs, skill players, linebackers, and defensive linemen until the selected population reaches the configured cap. Both arms may get different tattoos. Choose allowed designs in the Tattoo pool; Japanese and Polynesian styles are optional and start unchecked. Reset to Defaults leaves both styles unchecked, while All selects every design. Names identify the known style and body area; numbered custom designs keep their variant number because the source does not describe their artwork. Existing arm sleeves and tattoos stay as they are. Leg tattoos switch the player to low socks and bare legs so the ink remains visible. FBS and directional FCS populations are capped separately. <strong class="requirement">Requires CFB 27 Unlocked.</strong>`],["Player Pool","Skip NIL players starts on but can be turned off. Your team selection chooses who can be changed; empty means all teams. To skip teams, select All and uncheck those teams."]])}
  ${section("Long Snap Rating Fixer", "Creates more realistic Long Snap ratings, with tight ends generally rating higher than offensive linemen.", [["Tight ends","Only ratings outside 45–99 are rerolled, with most new ratings landing near 72."],["Offensive line","Only ratings outside 21–75 are rerolled, with most new ratings landing near 48."],["Already-valid ratings","Stay unchanged. No other player ratings are touched."]])}
  ${section("Team Boost", "Raises or lowers the ratings that matter most for each player's position and role.", [["Teams","Select one or more teams to change."],["Player Scope","All Players uses the full selected roster. Above or Below Position-Room Average compares each player only with teammates at the same position. The optional Positions filter narrows that scope without changing room averages."],["Specific Attributes","Select exactly which supported ratings to adjust. Each checked attribute uses your minimum–maximum range, even if it is not normally relevant to the position. Unchecked attributes stay unchanged."],["Minimum / maximum","Sets the smallest and largest possible change. Positive numbers raise ratings; negative numbers lower them."],["Physical","Speed, strength, agility, acceleration, change of direction, jumping, throw power, and kick power."],["Non-physical","Awareness, technique, ball skills, blocking, coverage, tackling, and other learned ratings that matter for the player's role."],["All relevant ratings","Combines both groups. Ratings always stay between 0 and 99."]])}
  ${section("NIL Toggle", "Changes only the NIL flag for active-roster players.", [["Target Value", "False permits in-game editing; True restricts it. This flag does not reliably identify real-life NIL players."], ["Player Scope", "Team, player, position, class year and redshirt filters work together. Leave all filters empty for the entire active dynasty roster."], ["Preview and Apply", "Preview lists all matches, including players already at the target value. Apply backs up first and changes only differing NIL flags."]])}
  ${section("Dealbreaker Fixer", "Replaces invalid or unwanted dealbreakers using your percentage choices and each player's situation.", [["Base percentages","Set the starting mix. The percentages must add up to exactly 100%."],["Player situation","Overall, class, position, playing-time competition, and quarterback depth can change what a player is most likely to receive."],["None percentage","Sets a minimum share of players with no dealbreaker so the tool does not hand out too many."],["Playing Style","Only running backs, wide receivers, and tight ends may receive it. The cleanup option removes it from players at other positions."]])}
  ${section("Smart Force Win", "Compares future regular-season matchups using current rosters, coaching, home field, and matchup fit.", [["Schedule scope","Check the rest of the regular season, the next playable week, or one future week."],["Tool involvement","Controls how large a mismatch must be before the toolkit steps in. Minimum is the most selective. Maximum assigns the favorite in every eligible matchup."],["Protect Favorites","Leaves close games and away rivalry favorites alone, may decide medium mismatches, and protects the favorite in high or extreme mismatches."],["Matchup model","Changes how much weight is given to roster strength, coaching, matchup fit, home field, and possible upsets."],["Team strength","Offense and defense are measured separately against the rest of the FBS. Position groups are also compared to show where one team has an advantage."],["Coaching continuity","Experienced staffs receive a small, limited boost. The head coach matters most, and first-year staffs receive no continuity bonus."],["Projection details","Open a matchup to see the ratings and adjustments behind the projected spread, over/under, win chance, and moneyline."],["Force FCS matchups","When enabled, a clearly stronger FBS team can be assigned as the winner once it meets the ratings advantage shown in the tool."],["Teams to skip","Selected teams are protected from changes. Your user-controlled teams start selected."],["Review and preview","First review your settings, then approve them to open the full schedule preview. Apply uses the winners shown in that preview without rolling them again."],["Clear action","Removes existing assignments from the games, week, or team you select."]])}`;
}

function settingsPage() {
  const teams = state.homeContext?.teams ?? [], selected = teams.find(team => team.name === state.selectedArtworkTeam) ?? teams[0], artwork = selected ? state.artwork[selected.name.trim().toLowerCase()] ?? {} : {};
  return `<div class="tool-header"><div><div class="eyebrow">Application</div><h1>Settings</h1></div></div><section class="card"><h2>Appearance</h2><label for="theme-select">Theme</label><select id="theme-select"><option value="light" ${state.bootstrap.settings.theme === "light" ? "selected" : ""}>Light</option><option value="dark" ${state.bootstrap.settings.theme === "dark" ? "selected" : ""}>Dark</option></select><label for="accent-color"><strong>App Color</strong></label><div class="accent-settings"><input id="accent-color" type="color" value="${escapeHtml(state.bootstrap.settings.accentColor ?? "#087a45")}" aria-label="Choose app accent color"><span id="accent-color-label">${escapeHtml(state.bootstrap.settings.accentColor ?? "Default green")}</span><button type="button" class="button secondary" id="accent-reset">Default Green</button></div><p class="muted">Choose your own accent color for buttons, highlights, and navigation. Colors adjust for readability in light and dark mode. Team logos and equipment colors do not change.</p><div class="settings-section-heading">Team Artwork</div><p class="muted">Choose images for a team in your Active Dynasty. Custom logos appear wherever that team is shown; a custom header appears on Home when you view that team. These images are stored in Toolkit settings and do not edit your save.</p>${selected ? `<label for="settings-artwork-team">Team</label><select id="settings-artwork-team">${teams.map(team => `<option value="${escapeHtml(team.name)}" ${team.name === selected.name ? "selected" : ""}>${escapeHtml(team.name)}</option>`).join("")}</select><div class="settings-artwork-grid"><div class="settings-artwork-item"><strong>Team Logo</strong><div class="settings-logo-preview"><img data-team-logo src="${forceLogoUrl(selected.name)}" alt="${escapeHtml(selected.name)} logo"></div><p class="muted">Upload a 1024 × 1024 PNG, JPG, or WebP image.</p><div class="actions"><button class="button secondary" data-artwork-upload="logo">Upload Logo</button>${artwork.logo ? '<button class="button secondary" data-artwork-clear="logo">Use Default</button>' : ""}</div></div><div class="settings-artwork-item"><strong>Home Header</strong><div class="settings-header-preview"><img data-team-header src="${artwork.header || teamHeaderUrl(selected.name)}" alt="Header for ${escapeHtml(selected.name)}"></div><p class="muted">The included team header is used by default. Teams without one use the general football header. You can upload a custom image of any supported size.</p><div class="actions"><button class="button secondary" data-artwork-upload="header">Upload Header</button>${artwork.header ? '<button class="button secondary" data-artwork-clear="header">Use Default</button>' : ""}</div></div></div>` : `<div class="notice">Select a supported Dynasty save to choose a team's artwork.</div>`}<div class="settings-section-heading">Active Save</div><p class="muted">${escapeHtml(state.activeSave?.path || "No save selected")}</p><div class="actions"><button class="button secondary" id="select-save">Change Save</button></div><p class="section muted">Theme, custom team artwork, and window size are remembered. Active Dynasty starts empty each time the app launches.</p></section>${window.toolkitUpdates?.settings() ?? ""}`;
}
function bindSettingsArtwork() {
  document.querySelector("#settings-artwork-team")?.addEventListener("change", event => { state.selectedArtworkTeam = event.target.value; render(); });
  document.querySelectorAll("[data-artwork-upload]").forEach(button => button.addEventListener("click", async () => {
    try {
      const kind = button.dataset.artworkUpload, teamName = document.querySelector("#settings-artwork-team")?.value;
      const result = await window.cfbToolkit.chooseTeamArtwork({ teamName, kind });
      if (!result) return;
      const entry = state.artwork[teamName.trim().toLowerCase()] ??= {};
      if (entry[kind]) { URL.revokeObjectURL(entry[kind]); state.artworkUrls.delete(entry[kind]); }
      entry[kind] = artworkObjectUrl(result.image);
      render(); toast(`${kind === "logo" ? "Logo" : "Header"} updated for ${teamName}`);
    } catch (error) { showError(readableError(error)); }
  }));
  document.querySelectorAll("[data-artwork-clear]").forEach(button => button.addEventListener("click", async () => {
    try {
      const kind = button.dataset.artworkClear, teamName = document.querySelector("#settings-artwork-team")?.value;
      await window.cfbToolkit.clearTeamArtwork({ teamName, kind });
      const entry = state.artwork[teamName.trim().toLowerCase()];
      if (entry?.[kind]) { URL.revokeObjectURL(entry[kind]); state.artworkUrls.delete(entry[kind]); delete entry[kind]; }
      render(); toast(`Default ${kind} restored for ${teamName}`);
    } catch (error) { showError(readableError(error)); }
  }));
}
function render() {
  if (state.page === "home") content.innerHTML = homePage();
  else if (state.page === "saved-review") { renderSavedReview(); return; }
  else if (state.page === "season-lines") { renderSeasonLines(); return; }
  else if (state.page === "help") content.innerHTML = helpPage();
  else if (state.page === "history") { historyPage(); return; }
  else if (state.page === "reports") { reportsPage(); return; }
  else if (state.page === "logs") { logsPage(); return; }
  else if (state.page === "settings") content.innerHTML = settingsPage();
  else if (state.page === "about") content.innerHTML = `<div class="hero"><div class="eyebrow">About</div><h1>Ace&#39;s CFB Toolkit</h1><p class="muted">Version ${escapeHtml(state.bootstrap.app.version)} · Supported schemas ${escapeHtml(state.bootstrap.app.schemas.join(", "))}</p><p>Manage your dynasty with clear previews, detailed reports, and backups before changes are applied.</p><p>Ace&#39;s CFB Toolkit is open source. You are free to copy, modify, reuse, or incorporate its tools and code into your own projects.</p></div>`;
  else { const tool = state.bootstrap.registry.tools.find(item => item.id === state.page); if (tool?.id === "nil-toggle" && tool.status === "available") { nilTogglePage(tool); return; } if (tool?.id === "team-boost" && tool.status === "available") { teamBoostPage(tool); return; } if (tool?.id === "jersey-renumber" && tool.status === "available") { jerseyPage(tool); return; } if (["freshman-equipment", "equipment-patcher"].includes(tool?.id) && tool.status === "available") { equipmentPage(tool); return; } if (tool?.id === "automatic-force-win" && tool.status === "available") { forceWinPage(tool); return; } if (tool?.id === "dealbreaker-fixer" && tool.status === "available") { dealbreakerPage(tool); return; } if (tool?.id === "commentary-id" && tool.status === "available") content.innerHTML = state.commentaryReview ? commentaryReviewPage(tool) : commentaryConfigPage(tool); else content.innerHTML = tool?.id === "long-snap" && tool.status === "available" ? longSnapPage(tool) : plannedTool(tool); }
  bindCommon(); if (state.page === "long-snap") bindRun("long-snap"); if (state.page === "commentary-id") { if (state.commentaryReview) { bindCommentaryReview(); bindCommentaryReviewFilters(); if (state.commentaryReview.autoSkipped) { showStandardPreviewStage(true); if (state.commentaryReview.lastResult) { renderResult(document.querySelector("#run-output"), state.commentaryReview.lastResult); document.querySelector("#commentary-apply").disabled = state.commentaryReview.lastResult.mode !== "preview"; } } } else bindCommentaryConfig(); }
}

document.querySelector("#change-save").addEventListener("click", chooseActiveSave);
document.querySelector("#sidebar-toggle").addEventListener("click", event => { document.body.classList.toggle("sidebar-collapsed"); event.currentTarget.setAttribute("aria-expanded", String(!document.body.classList.contains("sidebar-collapsed"))); });
window.cfbToolkit.bootstrap().then(async snapshot => { state.bootstrap = snapshot; document.documentElement.dataset.theme = snapshot.settings.theme === "dark" ? "dark" : "light"; applyAccentColor(snapshot.settings); document.querySelectorAll("#app-version,#topbar-app-version").forEach(label => label.textContent = `v${snapshot.app.version}`); state.activeSave = snapshot.activeSave; await refreshHistory(); buildNavigation(); updateActiveSave(); render(); }).catch(error => showError(readableError(error))).finally(() => document.querySelector("#startup-screen")?.remove());
